  // ══════════════════════════════════════════════════════════
  // Unit 3 · Node 3 · 그런데요…
  // A-(으)ㄴ데 / V-는데 / N인데
  //
  // 교재 p.47 연습 1
  //
  // 형용사
  // 크다      → 큰데
  // 작다      → 작은데
  // 따뜻하다  → 따뜻한데
  // 춥다      → 추운데
  // 맛있다    → 맛있는데
  // 재미없다  → 재미없는데
  // 좋았다    → 좋았는데
  // 예뻤다    → 예뻤는데
  //
  // 동사
  // 가다      → 가는데
  // 먹다      → 먹는데
  // 공부하다  → 공부하는데
  // 걷다      → 걷는데
  // 살다      → 사는데
  // 만들다    → 만드는데
  // 만났다    → 만났는데
  // 배웠다    → 배웠는데
  //
  // p.47 연습 2
  // [보기]
  // 요즘 한국어를 배우다 + 재미있다
  // → 요즘 한국어를 배우는데 재미있어요.
  //
  // 1) 학교에 가다 + 친구를 만났다
  // 2) 밥을 먹다 + 전화가 왔다
  // 3) 날씨가 춥다 + 따뜻한 옷이 없다
  // 4) 주말에 영화를 봤다 + 무서웠다
  // 5) 이 사람은 내 친구이다 + 노래를 잘하다
  // 6) 여기는 학생 식당이다 + 싸고 맛있다
  //
  // p.48 연습 3
  // [보기]
  // 배가 아픈데 약 있어요? (아프다)
  //
  // 1) 이 문제가 어려운데 좀 도와주세요.
  // 2) 사전이 없는데 좀 빌려 주세요.
  // 3) 잘 안 보이는데 좀 크게 써 주세요.
  // 4) 선생님 전화번호를 모르는데 좀 가르쳐 주세요.
  // 5) 아침에 지하철을 탔는데 사람이 정말 많았어요.
  // 6) 싸고 예쁜 옷을 사고 싶은데 어디에 가면 좋아요?
  //
  // p.48 연습 4
  // [보기]
  // 이것은 김치인데 한국 사람들이 매일 먹는 음식이에요.
  //
  // 1) 내 카메라 → 이것은 ...
  // 2) 내 동생   → 이 사람은 ...
  // 3) 우리 학교 → 여기는 ...
  //
  // ※ 1~3은 원본 자체가 자유 문장 생산 문제.
  //    교재에 고정된 뒷문장 정답이 없음.
  //    따라서 앱에서는
  //    "이것은 내 카메라인데 / 이 사람은 내 동생인데 /
  //     여기는 우리 학교인데"
  //    까지만 정확히 만드는 연습으로 처리.
  //
  // p.49 연습 5
  // -(으)ㄴ데/는데 vs -아서/어서
  //
  // [보기]
  // 어제 시장에 갔어요. 사람이 많았어요.
  // → 어제 시장에 갔는데 사람이 많았어요.
  //
  // 1) 어제 뮤지컬을 봤어요. 아주 재미있었어요.
  // 2) 이 음식이 맛있어요. 한번 드셔 보세요.
  // 3) 영화가 너무 재미없었어요. 잤어요.
  // 4) 태권도를 배우고 싶어요. 어디에서 배울 수 있어요?
  // 5) 친구가 학교에 안 왔어요. 친구 집에 전화를 해 봤어요.
  // 6) 다음 주에 친구하고 여행을 가려고 해요. 어디가 좋아요?
  // 7) 날씨가 더워요. 아이스크림을 먹을까요?
  // 8) 내일 시험이 있어요. 공부해야 돼요.
  // 9) 올해부터 대학원 공부를 시작했어요.
  //    ※ 원본에 두 번째 문장이 없음. 임의 추가 금지.
  // 10) 감기에 걸렸어요. 병원에 갔어요.
  //
  // Grammar 전용 문제 타입 사용 금지.
  // ══════════════════════════════════════════════════════════

  // ──────────────────────────────────────────────────────────
  // Lesson 1 · 어떻게 바뀌어요?
  // p.47 연습 1
  // ──────────────────────────────────────────────────────────

