  // ══════════════════════════════════════════════════════════
  // Unit 3 · Node 4 · 앞으로 할 일
  // V-(으)ㄹ N
  //
  // 교재 p.50 연습 1
  //
  // [보기]
  // 오늘 오후에 할 일이 많아요. (하다)
  //
  // 1) 어제 가족에게 줄 선물을 샀어요. (주다)
  // 2) 마실 물을 사러 가게에 가야 돼요. (마시다)
  // 3) 내일 아침에 먹을 음식이 없어요. (먹다)
  // 4) 버스에 사람이 많아서 앉을 자리가 없어요. (앉다)
  // 5) 요즘 너무 바빠서 친구들과 놀 시간이 없어요. (놀다)
  //
  // p.50 연습 2
  //
  // [보기]
  // A: 내일 시간 있어요?
  // B: 아니요, 내일은 할 일이 많아서 시간이 없어요.
  //
  // 1)
  // A: 뭘 샀어요?
  // B: 내일 등산하면서 마실 음료수를 샀어요.
  //
  // 2)
  // A: 이 영화 봤어요?
  // B: 아니요, 요즘 바빠서 영화 볼 시간이 없어요.
  //
  // 3)
  // A: 어디 가세요?
  // B: 내일 아침에 먹을 빵이 없어서 사러 가요.
  //
  // 4)
  // A: 뭐 하고 있어요?
  // B: 저녁에 모임이 있어서 입을 옷을 고르고 있어요.
  //
  // p.51 연습 3 · 다음 주 계획
  //
  // 11(월) 유진과 저녁 식사(닭갈비)
  // 12(화) 코엑스에서 마리코랑 쇼핑
  // 13(수) 수영
  // 14(목) 동호회 모임
  // 15(금) 유진이랑 명동에서 약속
  // 16(토) 친구들이랑 사물놀이 구경
  // 17(일) 경주 여행
  //
  // 이야기:
  // 월요일에 만날 친구는 유진 씨입니다.
  // 화요일에는 마리코 씨를 만나서 쇼핑을 할 계획입니다.
  // 친구들과 같이 볼 공연은 사물놀이입니다.
  // 이번에 갈 곳은 경주입니다.
  //
  // p.51 연습 4
  //
  // [보기]
  // 제가 다음 주에 (만난, 만날) 사람은 스티븐 씨예요.
  //
  // 1) 어제 (본, 볼) 영화 어땠어요? → 본
  // 2) 내일 같이 놀러 (간, 갈) 시간 있어요? → 갈
  // 3) 시장에 가서 일주일 동안 (먹은, 먹을) 음식을 사야 해요. → 먹을
  // 4) 지난주에 (산, 살) 가방을 잃어버렸어요. → 산
  // 5) 지난번에 (빌려 준, 빌려 줄) 책 다 읽었어요? → 빌려 준
  //
  // Grammar 전용 문제 타입 사용 금지.
  // ══════════════════════════════════════════════════════════

  // ──────────────────────────────────────────────────────────
  // Lesson 1 · 앞으로 무엇을 할까요?
  // p.50 연습 1
  // ──────────────────────────────────────────────────────────

