  // ══════════════════════════════════════════════════════════
  // Unit 3 · Node 5 · 문형 연습
  // 교재 p.52~53
  //
  // p.52 연습 1 · V-아/어 보다
  //
  // [보기]
  // T: 삼계탕을 먹어 봤어요?
  // S: (네) 네, 먹어 봤어요.
  //    (아니요) 아니요, 못 먹어 봤어요.
  //
  // 1) 불고기를 만들어 봤어요? → 네
  // 2) 부산에 가 봤어요? → 아니요
  // 3) 한국 음악을 들어 봤어요? → 네
  // 4) 한복을 입어 봤어요? → 아니요
  //
  // p.52 연습 2 · 상황 + 제안
  //
  // [보기]
  // 날씨가 좋다 + 산책하다
  // → 날씨가 좋은데 산책할까요?
  //
  // 1) 피곤하다 + 좀 쉬다
  // → 피곤한데 좀 쉴까요?
  //
  // 2) 날씨가 덥다 + 냉면을 먹다
  // → 날씨가 더운데 냉면을 먹을까요?
  //
  // 3) 시간이 없다 + 택시를 타다
  // → 시간이 없는데 택시를 탈까요?
  //
  // 4) 내일이 휴일이다 + 등산하러 가다
  // → 내일이 휴일인데 등산하러 갈까요?
  //
  // p.53 연습 3 · 두 문장 결합
  //
  // [보기]
  // 어제 명동에 갔어요. 사람이 아주 많았어요.
  // → 어제 명동에 갔는데 사람이 아주 많았어요.
  //
  // 1) 토요일에 산에 갔어요. 비가 왔어요.
  // → 토요일에 산에 갔는데 비가 왔어요.
  //
  // 2) 점심에 피자를 먹었어요. 맛있었어요.
  // → 점심에 피자를 먹었는데 맛있었어요.
  //
  // 3) 어제 영화를 봤어요. 재미있었어요.
  // → 어제 영화를 봤는데 재미있었어요.
  //
  // 4) 주말에 이 책을 읽었어요. 좀 어려웠어요.
  // → 주말에 이 책을 읽었는데 좀 어려웠어요.
  //
  // p.53 연습 4 · V-(으)ㄹ N
  //
  // [보기]
  // 마시다 + 물 + 없다
  // → 마실 물이 없어요.
  //
  // 1) 먹다 + 음식 + 없다
  // → 먹을 음식이 없어요.
  //
  // 2) 읽다 + 책 + 많다
  // → 읽을 책이 많아요.
  //
  // 3) 하다 + 일 + 있다
  // → 할 일이 있어요.
  //
  // 4) 입다 + 옷 + 없다
  // → 입을 옷이 없어요.
  //
  // Grammar 전용 문제 타입 사용 금지.
  // ══════════════════════════════════════════════════════════

